mapper.select:
select distinct org_id from system_store_info where deleted = b'0' and store_source = 0 and store_id in
#{storeId}
and org_id != 0

select org_id as orgId, count(store_id) as storeNum from system_store_info where deleted = b'0' and store_source = 0 and org_id in
#{unionId}
group by org_id

SELECT DISTINCT a.* FROM system_store_info a LEFT JOIN system_store_user su ON a.store_id = su.store_id AND su.type = 1 AND su.deleted = b'0' LEFT JOIN system_users u ON su.user_id = u.id AND u.deleted = b'0' WHERE a.deleted = b'0' AND a.store_source = 0
AND a.store_id IN ( SELECT st.store_id FROM system_store_tag st WHERE st.deleted = B'0' AND st.tag_id IN
#{tagId}
GROUP BY st.store_id HAVING COUNT(DISTINCT st.tag_id) = #{selectedTagCount} )
AND EXISTS ( SELECT 1 FROM system_store_tag st WHERE st.store_id = a.store_id AND st.deleted = B'0' AND st.tag_id IN
#{tagId}
)
AND NOT EXISTS ( SELECT 1 FROM system_store_tag st WHERE st.store_id = a.store_id AND st.deleted = B'0' )
AND EXISTS ( SELECT 1 FROM system_store_tag st WHERE st.store_id = a.store_id AND st.deleted = B'0' AND st.tag_id = #{record.tagId} )
AND NOT EXISTS ( SELECT 1 FROM system_store_tag st WHERE st.store_id = a.store_id AND st.deleted = B'0' )
AND ( a.store_name LIKE CONCAT('%', #{record.text}, '%') OR a.store_id LIKE CONCAT('%', #{record.text}, '%') )
AND ( u.nickname LIKE CONCAT('%', #{record.leaderText}, '%') OR u.mobile LIKE CONCAT('%', #{record.leaderText}, '%') )
AND a.store_status = #{record.storeStatus}
AND a.open_status = #{record.openStatus}
AND a.campus_delivery_status = #{record.campusDeliveryStatus}
AND a.business_id = #{businessId}
AND (
a.org_id IN
#{orgId}
1=1
OR su.user_id = #{userId}
) ORDER BY a.create_time DESC

