select distinct a.* , b.qr_type ,b.qr_code ,b.qr_community_code from system_store_info a left join store_wecom_config b on a.store_id = b.store_id left join system_store_user c on a.store_id = c.store_id LEFT JOIN system_store_tag d ON a.store_id = d.store_id AND d.deleted = b'0' where a.deleted = b'0' and a.store_source = 0 and a.store_status = 0
and a.store_name like concat('%', #{record.text}, '%')
and a.business_id = #{businessId}
AND ((b.qr_code IS NOT NULL AND b.qr_code != '' ) or ( b.qr_community_code IS NOT NULL AND b.qr_community_code != ''))
AND (( b.qr_code IS NULL OR b.qr_code = '' ) ) AND (( b.qr_community_code IS NULL OR b.qr_community_code = '' ) )
and a.org_id in
#{orgId}
or c.user_id = #{userId}
and d.tag_id in
#{rr}
ORDER BY a.create_time DESC

